import React from "react";
import styled from "styled-components";

// Sample data for engineers
const engineersData = [
  {
    fullName: "Nguyễn Văn A",
    phoneNumber: "0123456789",
    email: "nguyenvana@example.com",
    department: "Kỹ thuật",
    birthYear: "1990",
    gender: "Nam",
    role: "Kỹ sư phần mềm",
  },
  {
    fullName: "Trần Thị B",
    phoneNumber: "0987654321",
    email: "tranb@example.com",
    department: "Kinh doanh",
    birthYear: "1985",
    gender: "Nữ",
    role: "Trưởng phòng kinh doanh",
  },
  {
    fullName: "Phan Minh C",
    phoneNumber: "0333444555",
    email: "phanminhc@example.com",
    department: "Marketing",
    birthYear: "1992",
    gender: "Nam",
    role: "Chuyên viên marketing",
  },
  {
    fullName: "Lê Thị D",
    phoneNumber: "0999888777",
    email: "lethid@example.com",
    department: "Hỗ trợ khách hàng",
    birthYear: "1994",
    gender: "Nữ",
    role: "Nhân viên hỗ trợ",
  },
  {
    fullName: "Vũ Minh E",
    phoneNumber: "0888777666",
    email: "vumine@example.com",
    department: "Nghiên cứu",
    birthYear: "1988",
    gender: "Nam",
    role: "Nghiên cứu viên",
  },
  {
    fullName: "Đỗ Thị F",
    phoneNumber: "0777666555",
    email: "dothif@example.com",
    department: "Phát triển",
    birthYear: "1993",
    gender: "Nữ",
    role: "Chuyên viên phát triển",
  },
];

const Container = styled.div`
  margin-top: 50px;
  display: flex;
  justify-content: center;
  flex-direction: column;
  align-items: center;
`;

const Wrapper = styled.div`
  width: 90%;
  position: relative;
`;

const Title = styled.h2`
  margin-bottom: 30px;
  font-size: 24px;
  text-align: center;
`;

const AddEngineerButton = styled.button`
  position: absolute;
  top: 20px;
  right: 20px;
  padding: 10px 20px;
  background-color: #007bff;
  color: white;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  font-size: 16px;
  transition: background-color 0.3s;

  &:hover {
    background-color: #0056b3;
  }
`;

const EngineersContainer = styled.div`
  display: grid;
  grid-template-columns: repeat(3, 1fr);  // 3 cards per row
  gap: 20px;
  justify-items: center;
`;

const EngineerCard = styled.div`
  display: flex;
  flex-direction: column;
  background-color: #f9f9f9;
  padding: 20px;
  width: 400px;
  border: 1px solid #ddd;
  border-radius: 8px;
  text-align: center;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
`;

const EngineerAvatar = styled.div`
  width: 100px;
  height: 100px;
  border-radius: 50%;
  margin-bottom: 15px;
  overflow: hidden;
  margin-left: auto;
  margin-right: auto;
  background-image: url(${(props) => props.src});
  background-size: cover;
  background-position: center;
`;

const EngineerField = styled.div`
  margin: 8px 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
`;

const EngineerLabel = styled.span`
  font-weight: bold;
  color: #555;
  width: 100px;
  margin: 10px 0;
  text-align: left;
`;

const EngineerValue = styled.span`
  color: #333;
  flex: 1;
  text-align: left;
`;

const Engineers = () => {
  return (
    <Container>
      <Wrapper>
        <Title>Danh sách kỹ sư</Title>
        <AddEngineerButton>Thêm Kỹ sư</AddEngineerButton>
        <EngineersContainer>
          {engineersData.map((engineer, index) => (
            <EngineerCard key={index}>
              <EngineerAvatar
                src={
                  engineer.gender === "Nam"
                    ? "/default_avatar_male.jpg"
                    : "/default_avatar_female.jpg"
                }
              />
              <EngineerField>
                <EngineerLabel>Họ và tên:</EngineerLabel>
                <EngineerValue>{engineer.fullName}</EngineerValue>
                <EngineerLabel>Giới tính:</EngineerLabel>
                <EngineerValue>{engineer.gender}</EngineerValue>
              </EngineerField>
              <EngineerField>
                <EngineerLabel>Số điện thoại:</EngineerLabel>
                <EngineerValue>{engineer.phoneNumber}</EngineerValue>
                <EngineerLabel>Năm sinh:</EngineerLabel>
                <EngineerValue>{engineer.birthYear}</EngineerValue>
              </EngineerField>
              <EngineerField>
                <EngineerLabel>Email:</EngineerLabel>
                <EngineerValue>{engineer.email}</EngineerValue>
              </EngineerField>
              <EngineerField>
                <EngineerLabel>Phòng ban:</EngineerLabel>
                <EngineerValue>{engineer.department}</EngineerValue>
              </EngineerField>
              <EngineerField>
                <EngineerLabel>Vai trò:</EngineerLabel>
                <EngineerValue>{engineer.role}</EngineerValue>
              </EngineerField>
            </EngineerCard>
          ))}
        </EngineersContainer>
      </Wrapper>
    </Container>
  );
};

export default Engineers;
